// fixed
// Cloudflare Pages Function — POST /api/customer
// PUBLIC customer operations that legitimately need DB access, now that the
// anon key can no longer read the bookings table. Each action validates itself
// server-side; the Supabase SERVICE key never leaves the worker.
//
// Body: { action: string, ...args }
//   booked-slots        { date }                 -> string[]  (times only, no PII)
//   blackout-dates      {}                       -> string[]  (dates the shop is fully closed)
//   cancel-token        { id }                    -> { token } (HMAC, used when building cancel links)
//   cancel-verify       { id, token }             -> { valid, booking? }
//   cancel              { id, token }             -> { ok, booking? }
//   get-job             { id }                    -> Booking | null  (for estimate/invoice pages)
//   get-ppi             { id }                    -> PPIRecord | null (for the /ppi page)
//   sign                { id, signature }         -> { ok }   (customer e-signs estimate)
//   estimate-decline    { id }                    -> { ok }   (customer declines estimate)
//   returning-customer  { fname,lname,email,phone}-> { stripeCustomerId, last4 } | null

//   insert-booking       { row }                  -> { ok }   (customer booking + inquiry forms — resolves/creates a customer file)
//   send-inquiry        { row, fname,lname,phone,email,vehicle,notes,bookingId } -> { ok }  (inserts + emails atomically)
//   quick-quote         { name, phone, issue }    -> { ok }    (homepage fast-path form — texts the owner directly)

function json(body, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

// A phone number match alone is never enough to say two customer records
// are the same person — see admin-api-data.js's namesLikelyMatch for the
// full story (a shared phone silently merged 3 unrelated customers into
// one file). Kept identical here so the public lead-intake path can't
// reintroduce the same bug through a different door.
function namesLikelyMatch(fnameA, lnameA, fnameB, lnameB) {
  const norm = s => (s || '').trim().toLowerCase();
  const fa = norm(fnameA), fb = norm(fnameB);
  const la = norm(lnameA), lb = norm(lnameB);
  if (!fb && !lb) return true;
  if (fa !== fb) return false;
  if (!la || !lb) return true;
  return la === lb;
}

// HMAC-SHA256(secret, bookingId) -> 32-char hex. Replaces the old hardcoded-secret
// SHA-256 that lived in the browser bundle. Secret now comes from env only.
async function makeToken(bookingId, secret) {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw', enc.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false, ['sign']
  );
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(bookingId));
  return Array.from(new Uint8Array(sig))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('')
    .slice(0, 32);
}

// Constant-time-ish compare
function safeEqual(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string' || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

export async function onRequestPost({ request, env }) {
  const supabaseUrl = env.SUPABASE_URL ?? env.VITE_SUPABASE_URL;
  const serviceKey = env.SUPABASE_SERVICE_KEY;
  const cancelSecret = env.CANCEL_TOKEN_SECRET;
  const brevoKey = env.BREVO_API_KEY;
  if (!supabaseUrl || !serviceKey) {
    return json({ error: 'Server not configured' }, 500);
  }

  async function brevoSend(payload) {
    if (!brevoKey) { console.warn('BREVO_API_KEY not set'); return; }
    const r = await fetch('https://api.brevo.com/v3/smtp/email', {
      method: 'POST',
      headers: { 'api-key': brevoKey, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    if (!r.ok) console.error('Brevo send failed:', r.status, await r.text());
  }

  // Sends a text via Brevo's transactional SMS API. Requires a Brevo account
  // with SMS credits + an approved sender name (Brevo → Transactional →
  // SMS → Senders) — separate setup from the email side, even though it's
  // the same account/API key.
  async function brevoSendSms(to, content) {
    if (!brevoKey) { console.warn('BREVO_API_KEY not set'); return false; }
    const r = await fetch('https://api.brevo.com/v3/transactionalSMS/sms', {
      method: 'POST',
      headers: { 'api-key': brevoKey, 'Content-Type': 'application/json' },
      body: JSON.stringify({ sender: 'GIDGarage', recipient: to, content, type: 'transactional' }),
    });
    if (!r.ok) { console.error('Brevo SMS failed:', r.status, await r.text()); return false; }
    return true;
  }

  const base = `${supabaseUrl}/rest/v1`;
  const headers = {
    apikey: serviceKey,
    Authorization: `Bearer ${serviceKey}`,
    'Content-Type': 'application/json',
  };

  // Resolves a booking's contact info to a single customer file, creating
  // one if none matches — same dedupe rule as admin-api-data's
  // find-or-create-customer (phone digits if present, else name+email),
  // kept in sync deliberately so a lead coming through the public site
  // resolves to the same file it would if entered manually as an External
  // Lead. Never throws — a customer-linking hiccup should never block a
  // real booking from saving.
  async function findOrCreateCustomerId({ fname, lname, phone, email, vehicle }) {
    if (!fname) return null;
    try {
      const phoneDigits = (phone || '').replace(/\D/g, '');
      let existing = [];
      if (phoneDigits) {
        const r = await fetch(`${base}/customers?select=id,phone,fname,lname`, { headers });
        if (r.ok) {
          const all = await r.json();
          existing = all
            .filter(c => (c.phone || '').replace(/\D/g, '') === phoneDigits)
            .filter(c => namesLikelyMatch(fname, lname, c.fname, c.lname));
        }
      } else {
        const r = await fetch(
          `${base}/customers?select=id&fname=ilike.${encodeURIComponent(fname)}&lname=ilike.${encodeURIComponent(lname || '')}&email=ilike.${encodeURIComponent(email || '')}`,
          { headers }
        );
        if (r.ok) existing = await r.json();
      }
      if (existing.length > 0) return existing[0].id;

      const insertRes = await fetch(`${base}/customers`, {
        method: 'POST',
        headers: { ...headers, Prefer: 'return=representation' },
        body: JSON.stringify({ fname, lname: lname || '', phone: phone || null, email: email || null, vehicle: vehicle || null }),
      });
      if (!insertRes.ok) return null;
      const rows = await insertRes.json();
      return (Array.isArray(rows) ? rows[0] : rows)?.id ?? null;
    } catch (e) {
      console.error('findOrCreateCustomerId failed:', e.message);
      return null;
    }
  }

  // Current AZ TPT rate as a decimal (e.g. 0.09386 for 9.386%) — same source of
  // truth as the admin Hub → Taxes setting. Falls back to the historical
  // Flagstaff rate if the settings row is ever missing.
  async function fetchCurrentTaxRate() {
    try {
      const r = await fetch(`${base}/business_settings?id=eq.default&select=tax_rate`, { headers });
      if (!r.ok) return 0.09386;
      const rows = await r.json();
      return rows?.[0]?.tax_rate != null ? Number(rows[0].tax_rate) : 0.09386;
    } catch {
      return 0.09386;
    }
  }

  let payload;
  try {
    payload = await request.json();
  } catch {
    return json({ error: 'Invalid JSON' }, 400);
  }

  const { action } = payload;

  try {
    switch (action) {
      // ---- Availability (no PII leaves the worker) -------------------------
      case 'booked-slots': {
        const { date } = payload;
        if (!date) return json({ error: 'Missing date' }, 400);
        const res = await fetch(
          `${base}/bookings?select=time&date=eq.${encodeURIComponent(date)}&status=not.in.(cancelled,pending)`,
          { headers }
        );
        if (!res.ok) return json({ error: await res.text() }, 502);
        const rows = await res.json();
        return json(rows.map((r) => r.time));
      }

      // ---- Blackout dates (read-only here — admin manages them) -----------
      case 'blackout-dates': {
        // Phoenix is UTC-7 year-round — using raw UTC here would drop "today"
        // from the list 7 hours before Phoenix midnight actually arrives.
        const phoenixToday = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Phoenix' });
        const res = await fetch(
          `${base}/blackout_dates?select=date&date=gte.${phoenixToday}`,
          { headers }
        );
        if (!res.ok) return json([]); // fail open — never block booking entirely over this
        const rows = await res.json();
        return json(rows.map((r) => r.date));
      }

      // ---- Cancel-link token (built when sending confirmation email) -------
      case 'cancel-token': {
        const { id } = payload;
        if (!id) return json({ error: 'Missing id' }, 400);
        if (!cancelSecret) return json({ error: 'Cancel secret not configured' }, 500);
        return json({ token: await makeToken(id, cancelSecret) });
      }

      // ---- Verify a cancel link before showing the confirm UI --------------
      case 'cancel-verify': {
        const { id, token } = payload;
        if (!id || !token) return json({ valid: false });
        if (!cancelSecret) return json({ valid: false });
        const expected = await makeToken(id, cancelSecret);
        if (!safeEqual(expected, token)) return json({ valid: false });
        const res = await fetch(
          `${base}/bookings?id=eq.${encodeURIComponent(id)}&select=*`,
          { headers }
        );
        if (!res.ok) return json({ valid: false });
        const rows = await res.json();
        return json({ valid: true, booking: rows[0] ?? null });
      }

      // ---- Perform the cancellation ---------------------------------------
      case 'cancel': {
        const { id, token } = payload;
        if (!id || !token) return json({ error: 'Missing id or token' }, 400);
        if (!cancelSecret) return json({ error: 'Cancel secret not configured' }, 500);
        const expected = await makeToken(id, cancelSecret);
        if (!safeEqual(expected, token)) return json({ error: 'Invalid token' }, 403);

        // Read the row first so the client can send the cancellation email.
        const readRes = await fetch(
          `${base}/bookings?id=eq.${encodeURIComponent(id)}&select=*`,
          { headers }
        );
        const rows = readRes.ok ? await readRes.json() : [];
        const booking = rows[0] ?? null;

        const res = await fetch(
          `${base}/bookings?id=eq.${encodeURIComponent(id)}`,
          {
            method: 'PATCH',
            headers: { ...headers, Prefer: 'return=minimal' },
            body: JSON.stringify({ status: 'cancelled', job_status: 'CANCELLED' }),
          }
        );
        if (!res.ok) return json({ error: await res.text() }, 502);
        return json({ ok: true, booking });
      }

      // ---- Estimate / invoice page: read one job by id ---------------------
      case 'get-job': {
        const { id } = payload;
        if (!id) return json({ error: 'Missing id' }, 400);
        const res = await fetch(
          `${base}/bookings?id=eq.${encodeURIComponent(id)}&select=*`,
          { headers }
        );
        if (!res.ok) return json({ error: await res.text() }, 502);
        const rows = await res.json();
        const booking = rows[0] ?? null;
        if (!booking) return json(null);
        booking.currentTaxRate = await fetchCurrentTaxRate();
        return json(booking);
      }

      // ---- PrePI page: read one pre-purchase inspection by id ---------------
      case 'get-ppi': {
        const { id } = payload;
        if (!id) return json({ error: 'Missing id' }, 400);
        const res = await fetch(
          `${base}/ppi_inspections?id=eq.${encodeURIComponent(id)}&select=*`,
          { headers }
        );
        if (!res.ok) return json({ error: await res.text() }, 502);
        const rows = await res.json();
        return json(rows[0] ?? null);
      }

      // ---- Customer e-signs the estimate -----------------------------------
      case 'sign': {
        const { id, signature, damage, signerIp } = payload;
        if (!id || !signature) return json({ error: 'Missing id or signature' }, 400);
        const res = await fetch(
          `${base}/bookings?id=eq.${encodeURIComponent(id)}`,
          {
            method: 'PATCH',
            headers: { ...headers, Prefer: 'return=representation' },
            body: JSON.stringify({
              customer_agreed: true,
              customer_signature: String(signature).slice(0, 200),
              signed_at: new Date().toISOString(),
              job_status: 'SIGNED',
              ...(damage !== undefined ? { pre_existing_damage: String(damage).slice(0, 2000) } : {}),
              ...(signerIp ? { signed_ip: String(signerIp).slice(0, 64) } : {}),
            }),
          }
        );
        if (!res.ok) return json({ error: await res.text() }, 502);
        const rows = await res.json().catch(() => []);
        const booking = rows[0];

        // Notify the shop owner — email always fires; the event row feeds the
        // same local-notification system already used for payment alerts (shows
        // up as a push-style notification whenever the admin panel/PWA is open).
        if (booking) {
          const customerName = `${booking.fname} ${booking.lname}`;
          const total = (Number(booking.estimate_amount) || 0) + (Number(booking.tax_amount) || 0);
          try {
            await brevoSend({
              sender: { name: 'GID Garage', email: 'bookings@gidgarage.com' },
              to: [{ email: 'info@gidgarage.com', name: 'GID Garage' }],
              subject: `✅ Estimate Signed — ${customerName} — $${total.toFixed(2)}`,
              htmlContent: `<div style="font-family:sans-serif;padding:24px;background:#0f0f0f;color:#fff;"><h2 style="color:#22c55e;">Estimate Signed</h2><p><strong>${customerName}</strong><br>${booking.phone || ''}<br>${booking.email || ''}</p><p><strong>${booking.vehicle || ''}</strong><br>${booking.service || ''}</p><p style="font-size:20px;font-weight:bold;color:#22c55e;">$${total.toFixed(2)}</p>${damage ? `<p>Pre-existing damage noted: ${String(damage).slice(0, 300)}</p>` : ''}</div>`,
            });
          } catch (e) { console.error('Signed-estimate owner email failed:', e.message); }

          try {
            await fetch(`${base}/payment_events`, {
              method: 'POST',
              headers: { ...headers, Prefer: 'return=minimal' },
              body: JSON.stringify({ booking_id: id, event_type: 'signed', amount: total, error_message: null }),
            });
          } catch (e) { console.error('Signed-estimate event write failed:', e.message); }
        }

        return json({ ok: true });
      }

      // ---- Customer declines the estimate ----------------------------------
      case 'estimate-decline': {
        const { id } = payload;
        if (!id) return json({ error: 'Missing id' }, 400);
        const res = await fetch(
          `${base}/bookings?id=eq.${encodeURIComponent(id)}`,
          {
            method: 'PATCH',
            headers: { ...headers, Prefer: 'return=minimal' },
            body: JSON.stringify({
              customer_agreed: false,
              customer_signature: '',
              signed_at: null,
              job_status: 'BOOKED',
            }),
          }
        );
        if (!res.ok) return json({ error: await res.text() }, 502);
        return json({ ok: true });
      }

      // ---- Returning-customer card-on-file lookup --------------------------
      // Requires an exact name + email + phone match; returns only the Stripe
      // customer id + last4 (never the full row).
      case 'returning-customer': {
        const { fname, lname, email, phone } = payload;
        if (!fname || !lname || !email || !phone) return json(null);
        const digits = String(phone).replace(/\D/g, '');
        const dash = digits.replace(/^(\d{3})(\d{3})(\d{4})$/, '$1-$2-$3');
        const url =
          `${base}/bookings?select=stripe_customer_id,stripe_last4` +
          `&fname=ilike.${encodeURIComponent(fname)}` +
          `&lname=ilike.${encodeURIComponent(lname)}` +
          `&email=ilike.${encodeURIComponent(email)}` +
          `&or=(phone.eq.${digits},phone.eq.${dash})` +
          `&stripe_customer_id=not.is.null&order=created_at.desc&limit=1`;
        const res = await fetch(url, { headers });
        if (!res.ok) return json(null);
        const rows = await res.json();
        if (rows.length && rows[0].stripe_customer_id) {
          return json({ stripeCustomerId: rows[0].stripe_customer_id, last4: rows[0].stripe_last4 ?? null });
        }
        return json(null);
      }

      // ---- Booking confirmation email (customer + owner) ----------------
      case 'send-confirmation': {
        const { booking, cancelUrl, serviceName, dateStr } = payload;
        if (!booking) return json({ error: 'Missing booking' }, 400);
        const customerName = `${booking.fname} ${booking.lname}`;
        // Customer via Brevo template
        try {
          await brevoSend({
            sender: { name: 'GID Garage', email: 'bookings@gidgarage.com' },
            to: [{ email: booking.email, name: customerName }],
            templateId: 1,
            params: {
              to_name: booking.fname,
              service_name: serviceName,
              appointment_date: dateStr,
              appointment_time: booking.time,
              vehicle: booking.vehicle,
              notes: booking.notes || 'None',
              booking_id: booking.id,
              cancel_url: cancelUrl || '',
            },
          });
        } catch (e) { console.error('Customer confirmation email failed:', e.message); }
        // Owner notification for this booking already went out server-side
        // (save-card / confirm-booking, at the moment the booking was
        // actually confirmed) — not repeated here, since this call depends
        // on the customer's browser still being open after that point and
        // would just duplicate an alert that may or may not have fired.
        return json({ ok: true });
      }

      // ---- Cancellation notification (customer + owner) ------------------
      case 'send-cancellation': {
        const { booking } = payload;
        if (!booking) return json({ error: 'Missing booking' }, 400);
        const customerName = `${booking.fname} ${booking.lname}`;

        // Pretty service name map — mirrors SERVICES in BookingWidget.tsx
        const SERVICE_NAMES = {
          oil: 'Oil Change',
          brakes: 'Brake Service',
          diag: 'Diagnostics',
          suspension: 'Suspension Service',
          audio: 'Car Audio Install',
          full: 'Full Service Inspection',
          other: 'Custom Service',
        };
        const svcName = SERVICE_NAMES[booking.service] || booking.service || 'Appointment';

        // Format date in Flagstaff local time (America/Phoenix — no DST)
        const dateStr = booking.date
          ? new Date(booking.date + 'T12:00:00').toLocaleDateString('en-US', {
              weekday: 'long', month: 'long', day: 'numeric', year: 'numeric',
              timeZone: 'America/Phoenix',
            })
          : booking.date || '';

        const timeStr = booking.time || '';
        const apptLine = timeStr ? `${dateStr} at ${timeStr} (MST)` : dateStr;

        // Owner
        try {
          await brevoSend({
            sender: { name: 'GID Garage Bookings', email: 'bookings@gidgarage.com' },
            to: [{ email: 'info@gidgarage.com', name: 'GID Garage' }],
            subject: `❌ Cancellation: ${customerName} — ${svcName} on ${dateStr}`,
            htmlContent: `<div style="font-family:sans-serif;padding:24px;background:#0f0f0f;color:#fff;"><h2 style="color:#ef4444;">❌ Booking Cancelled</h2><p><strong>${customerName}</strong><br>${booking.phone}<br>${booking.email}</p><p>${svcName}<br>${apptLine}<br>${booking.vehicle}</p></div>`,
          });
        } catch (e) { console.error('Owner cancellation email failed:', e.message); }

        // Customer
        try {
          await brevoSend({
            sender: { name: 'GID Garage', email: 'bookings@gidgarage.com' },
            to: [{ email: booking.email, name: customerName }],
            subject: `Your ${svcName} appointment has been cancelled — GID Garage`,
            htmlContent: `<div style="font-family:sans-serif;max-width:560px;margin:0 auto;background:#0f0f0f;color:#fff;padding:32px;">
  <img src="https://gidgarage.com/website_logo.png" alt="GID Garage" style="height:48px;margin-bottom:28px;"/>
  <h2 style="color:#ef4444;font-size:22px;font-weight:900;margin:0 0 8px;">Appointment Cancelled</h2>
  <p style="color:#6b7280;font-size:13px;margin:0 0 28px;">We've received your cancellation request.</p>
  <table style="width:100%;border-collapse:collapse;background:#111827;border:1px solid #1f2937;margin-bottom:24px;">
    <tr><td style="padding:14px 16px;border-bottom:1px solid #1f2937;">
      <p style="color:#6b7280;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;margin:0 0 3px;">Service</p>
      <p style="color:#fff;font-size:15px;font-weight:700;margin:0;">${svcName}</p>
    </td></tr>
    <tr><td style="padding:14px 16px;border-bottom:1px solid #1f2937;">
      <p style="color:#6b7280;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;margin:0 0 3px;">Scheduled For</p>
      <p style="color:#fff;font-size:15px;font-weight:700;margin:0;">${apptLine}</p>
    </td></tr>
    <tr><td style="padding:14px 16px;">
      <p style="color:#6b7280;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;margin:0 0 3px;">Vehicle</p>
      <p style="color:#fff;font-size:15px;font-weight:700;margin:0;">${booking.vehicle || '—'}</p>
    </td></tr>
  </table>
  <div style="background:#1c1917;border-left:3px solid #f59e0b;padding:14px 16px;margin-bottom:28px;">
    <p style="color:#fcd34d;font-size:13px;font-weight:700;margin:0 0 4px;">Was this a mistake?</p>
    <p style="color:#9ca3af;font-size:13px;margin:0;">No worries — rebooking takes less than a minute. Just pick a new time and we'll get you back on the schedule.</p>
  </div>
  <a href="https://gidgarage.com/bookings" style="display:inline-block;background:#dc2626;color:#fff;text-decoration:none;font-weight:900;font-size:13px;padding:14px 32px;letter-spacing:0.08em;text-transform:uppercase;margin-bottom:28px;">BOOK A NEW APPOINTMENT →</a>
  <p style="color:#4b5563;font-size:11px;margin:0;">Questions? Call or text <strong style="color:#9ca3af;">480-757-0476</strong> — GID Garage, Flagstaff AZ</p>
</div>`,
          });
        } catch (e) { console.error('Customer cancellation email failed:', e.message); }
        return json({ ok: true });
      }

      // ---- Confirm booking for returning customers (bypass save-card) ----
      case 'confirm-booking': {
        const { id, stripeCustomerId, stripeLast4 } = payload;
        if (!id) return json({ error: 'Missing id' }, 400);
        const res = await fetch(
          `${base}/bookings?id=eq.${encodeURIComponent(id)}`,
          {
            method: 'PATCH',
            headers: { ...headers, Prefer: 'return=representation' },
            body: JSON.stringify({
              status: 'confirmed',
              ...(stripeCustomerId ? { stripe_customer_id: stripeCustomerId } : {}),
              ...(stripeLast4 ? { stripe_last4: stripeLast4 } : {}),
            }),
          }
        );
        if (!res.ok) return json({ error: await res.text() }, 502);

        // Owner alert fires here, server-side, at the moment the booking
        // actually becomes confirmed — not from the client's later
        // send-confirmation call, which depends on the customer's browser
        // staying open after this point. That gap was letting some
        // standard bookings go through with no admin notification.
        try {
          const rows = await res.json();
          const row = rows[0];
          if (row) {
            await brevoSend({
              sender: { name: 'GID Garage Bookings', email: 'bookings@gidgarage.com' },
              to: [{ email: 'info@gidgarage.com', name: 'GID Garage' }],
              subject: `New Booking: ${row.fname} ${row.lname} — ${row.service} on ${row.date}`,
              htmlContent: `<div style="font-family:sans-serif;padding:24px;background:#0f0f0f;color:#fff;"><h2 style="color:#ef4444;">New Booking</h2><p><strong>${row.fname} ${row.lname}</strong><br>${row.phone}<br>${row.email || ''}</p><p><strong>${row.service}</strong><br>${row.date} at ${row.time}<br>${row.vehicle || ''}</p>${row.notes ? `<p>Notes: ${row.notes}</p>` : ''}</div>`,
            });
          }
        } catch (e) { console.error('Owner notification (confirm-booking) failed:', e.message); }

        return json({ ok: true });
      }

      // ---- Inquiry / quote-request notification (owner only) -----------
      // Inserts the booking row AND sends the owner alert in one server
      // call — mirrors quick-quote's pattern. Previously the client made
      // two separate calls (insert-booking, then send-inquiry); if the
      // customer closed the tab or lost connection between them, the
      // inquiry would save with no notification ever going out.
      case 'send-inquiry': {
        const { row, fname, lname, phone, email, vehicle, notes, bookingId } = payload;
        const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

        if (row) {
          try {
            const customerId = await findOrCreateCustomerId({ fname: row.fname, lname: row.lname, phone: row.phone, email: row.email, vehicle: row.vehicle });
            const res = await fetch(`${base}/bookings`, {
              method: 'POST',
              headers: { ...headers, Prefer: 'return=minimal' },
              body: JSON.stringify(customerId ? { ...row, customer_id: customerId } : row),
            });
            if (!res.ok) return json({ error: await res.text() }, 502);
          } catch (e) { return json({ error: e.message ?? 'Insert failed' }, 500); }
        }

        try {
          await brevoSend({
            sender: { name: 'GID Garage Bookings', email: 'bookings@gidgarage.com' },
            to: [{ email: 'info@gidgarage.com', name: 'GID Garage' }],
            subject: `💬 New Inquiry: ${esc(fname)} ${esc(lname)}`,
            htmlContent: `<div style="font-family:sans-serif;max-width:520px;margin:0 auto;background:#0f0f0f;color:#fff;padding:32px;border-top:4px solid #dc2626;"><h2 style="margin:0 0 20px;font-size:22px;font-weight:900;">New Customer Inquiry</h2><table style="width:100%;border-collapse:collapse;font-size:13px;"><tr><td style="padding:8px 0;border-bottom:1px solid #1f2937;color:#9ca3af;width:35%;">Name</td><td style="padding:8px 0;border-bottom:1px solid #1f2937;font-weight:600;">${esc(fname)} ${esc(lname)}</td></tr><tr><td style="padding:8px 0;border-bottom:1px solid #1f2937;color:#9ca3af;">Phone</td><td style="padding:8px 0;border-bottom:1px solid #1f2937;">${esc(phone)}</td></tr>${email ? `<tr><td style="padding:8px 0;border-bottom:1px solid #1f2937;color:#9ca3af;">Email</td><td style="padding:8px 0;border-bottom:1px solid #1f2937;">${esc(email)}</td></tr>` : ''}${vehicle ? `<tr><td style="padding:8px 0;border-bottom:1px solid #1f2937;color:#9ca3af;">Vehicle</td><td style="padding:8px 0;border-bottom:1px solid #1f2937;">${esc(vehicle)}</td></tr>` : ''}</table><div style="margin-top:20px;background:#1a1a1a;border-left:3px solid #dc2626;padding:14px 16px;"><p style="color:#9ca3af;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.1em;margin:0 0 8px;">Problem Description</p><p style="margin:0;font-size:14px;line-height:1.6;color:#e5e7eb;">${esc(notes)}</p></div><p style="margin-top:20px;font-size:12px;color:#6b7280;">Job ID: ${esc(bookingId)} · Submitted ${new Date().toLocaleString('en-US', { timeZone: 'America/Phoenix' })}</p></div>`,
          });
        } catch (e) { console.error('Inquiry email failed:', e.message); }
        return json({ ok: true });
      }

      // ---- Quick Quote (homepage fast-path form) ----------------------------
      // Deliberately lighter than send-inquiry/insert-booking — 3 fields, no
      // DB row, texts the owner directly so a fast-moving lead doesn't sit in
      // an inbox. Falls back to email if SMS isn't configured or fails, so a
      // lead is never silently dropped.
      case 'quick-quote': {
        const { name, phone, year, make, model, engine, issue, hp } = payload; // hp = honeypot field, humans never fill it
        if (hp) return json({ ok: true }); // silently drop bot submissions
        if (!name || !phone) return json({ error: 'Missing name or phone' }, 400);
        const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

        const nameParts = name.trim().split(/\s+/);
        const fname = nameParts[0] || name;
        const lname = nameParts.slice(1).join(' ') || '';
        const bookingId = `GID-${Date.now()}`;
        const today = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Phoenix' });
        const nowTime = new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'America/Phoenix' });
        const submittedStr = new Date().toLocaleString('en-US', { timeZone: 'America/Phoenix' });
        const vehicle = [year, make, model, engine].map(v => (v || '').trim()).filter(Boolean).join(' ') || 'Not specified';

        // Insert as a real job row (status confirmed / job_status BOOKED) so it
        // shows up in admin > Jobs alongside everything else — a quick-quote
        // lead should never depend on an email/SMS landing to be visible.
        try {
          const customerId = await findOrCreateCustomerId({ fname, lname, phone, email: '', vehicle });
          const res = await fetch(`${base}/bookings`, {
            method: 'POST',
            headers: { ...headers, Prefer: 'return=minimal' },
            body: JSON.stringify({
              id: bookingId,
              service: 'quote',
              service_icon: '⚡',
              date: today,
              time: nowTime,
              fname, lname,
              phone,
              email: '',
              vehicle,
              notes: issue || '(nothing entered)',
              garage_notes: '',
              status: 'confirmed',
              job_status: 'BOOKED',
              created_at: new Date().toISOString(),
              ...(customerId ? { customer_id: customerId } : {}),
            }),
          });
          if (!res.ok) console.error('quick-quote booking insert failed:', await res.text());
        } catch (e) { console.error('quick-quote booking insert failed:', e.message); }

        // Command Center: log this as a lead too (source = website_form).
        // Best-effort — never let a leads-table hiccup break the actual quote flow.
        try {
          await fetch(`${base}/leads`, {
            method: 'POST',
            headers: { ...headers, Prefer: 'return=minimal' },
            body: JSON.stringify({
              fname, lname, phone, email: '',
              source: 'website_form',
              vehicle,
              requested_service: issue || '',
              status: 'new',
              booking_id: bookingId,
            }),
          });
        } catch (e) { console.error('quick-quote lead insert failed:', e.message); }

        try {
          await brevoSend({
            sender: { name: 'GID Garage Bookings', email: 'bookings@gidgarage.com' },
            to: [{ email: 'info@gidgarage.com', name: 'GID Garage' }],
            subject: `⚡ Quick Quote Request: ${esc(name)}`,
            htmlContent: `<div style="font-family:sans-serif;max-width:520px;margin:0 auto;background:#0f0f0f;color:#fff;padding:32px;border-top:4px solid #dc2626;"><h2 style="margin:0 0 20px;font-size:22px;font-weight:900;">⚡ Quick Quote Request</h2><table style="width:100%;border-collapse:collapse;font-size:13px;"><tr><td style="padding:8px 0;border-bottom:1px solid #1f2937;color:#9ca3af;width:35%;">Name</td><td style="padding:8px 0;border-bottom:1px solid #1f2937;font-weight:600;">${esc(name)}</td></tr><tr><td style="padding:8px 0;border-bottom:1px solid #1f2937;color:#9ca3af;">Phone</td><td style="padding:8px 0;border-bottom:1px solid #1f2937;">${esc(phone)}</td></tr><tr><td style="padding:8px 0;border-bottom:1px solid #1f2937;color:#9ca3af;">Vehicle</td><td style="padding:8px 0;border-bottom:1px solid #1f2937;">${esc(vehicle)}</td></tr></table><div style="margin-top:20px;background:#1a1a1a;border-left:3px solid #dc2626;padding:14px 16px;"><p style="color:#9ca3af;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.1em;margin:0 0 8px;">What's going on</p><p style="margin:0;font-size:14px;line-height:1.6;color:#e5e7eb;">${esc(issue || '(nothing entered)')}</p></div><p style="margin-top:20px;font-size:12px;color:#6b7280;">Job ID: ${esc(bookingId)} · Submitted ${submittedStr}</p></div>`,
          });
        } catch (e) { console.error('quick-quote email failed:', e.message); }
        return json({ ok: true });
      }

      // ---- Insert a new booking (customer booking + inquiry forms) --------
      case 'insert-booking': {
        const { row } = payload;
        if (!row) return json({ error: 'Missing row' }, 400);
        // Authoritative server-side check — the calendar UI already hides
        // blacked-out dates, but a stale page or a direct API call shouldn't
        // be able to slip a booking onto a day the shop marked closed.
        if (row.date) {
          const blackoutRes = await fetch(
            `${base}/blackout_dates?select=date&date=eq.${encodeURIComponent(row.date)}`,
            { headers }
          );
          if (blackoutRes.ok) {
            const hits = await blackoutRes.json();
            if (hits.length) return json({ error: 'That date is unavailable. Please pick another date.' }, 409);
          }
        }
        const customerId = await findOrCreateCustomerId({ fname: row.fname, lname: row.lname, phone: row.phone, email: row.email, vehicle: row.vehicle });
        const res = await fetch(`${base}/bookings`, {
          method: 'POST',
          headers: { ...headers, Prefer: 'return=minimal' },
          body: JSON.stringify(customerId ? { ...row, customer_id: customerId } : row),
        });
        if (!res.ok) return json({ error: await res.text() }, 502);

        // Command Center: log this as an already-booked lead (source =
        // website_booking) so the funnel counts direct bookings too, not
        // just quote-form submissions. Best-effort — never block the
        // actual booking on this.
        try {
          await fetch(`${base}/leads`, {
            method: 'POST',
            headers: { ...headers, Prefer: 'return=minimal' },
            body: JSON.stringify({
              fname: row.fname, lname: row.lname, phone: row.phone, email: row.email,
              source: 'website_booking',
              vehicle: row.vehicle,
              requested_service: row.service || '',
              quote_amount: row.estimate_amount ?? null,
              status: 'booked',
              booking_id: row.id,
              customer_id: customerId || null,
              last_contacted_at: new Date().toISOString(),
            }),
          });
        } catch (e) { console.error('insert-booking lead insert failed:', e.message); }

        return json({ ok: true });
      }

      default:
        return json({ error: `Unknown action: ${action}` }, 400);
    }
  } catch (err) {
    return json({ error: err.message ?? 'Unknown error' }, 500);
  }
}
